import { test } from "@e2e/fixtures";
import * as flows from "@e2e/flows";

test.describe("Agent diagnostic events", () => {
  test.describe.configure({ timeout: 180_000 });

  test.use({
    inspectorOptions: {
      inspectMode: true,
    },
  });

  test("Sub-agent invoked and stopped events appear after custom tool success trigger", async ({
    inspectorPage,
  }) => {
    await flows.agent.triggerCustomToolSuccessAndAssertEvents(inspectorPage);
  });

  test("Sub-agent success trigger shows events and opens details panel", async ({
    inspectorPage,
  }) => {
    await flows.agent.triggerAgentSuccessAndAssertEvents(inspectorPage);
    await flows.agent.openSubAgentEventDetailsAndAssert(inspectorPage);
  });
});
